import os

# ============================================================
#  NASTAVENÍ - UPRAV DLE POTŘEBY
# ============================================================
POCET_DAVEK = 10          # Kolikrát se má zopakovat cyklus (generuj -> komprimuj -> smaž .txt)
LIMIT_MISTA = 50         # Při kolika % zaplnění disku se uloží dávka (doporučeno 80)
NAZEV_DAT = "vsechny_davky.dat"   # Název výsledného komprimovaného souboru
NAZEV_TXT = "vysledky.txt"        # Název dočasného .txt souboru (bude mazán po každé dávce)
# ============================================================

def kontrola_volneho_mista():
    try:
        stat = os.statvfs('/')
        volne_misto = stat[0] * stat[3]
        celkove_misto = stat[0] * stat[2]
        return (volne_misto / celkove_misto) * 100
    except:
        return 100

def pridej_davku_do_souboru(cislo_davky, x_start, inkrement, konstanta, pocet_radku):
    """Přidá metadata jedné dávky do společného .dat souboru"""
    try:
        with open(NAZEV_DAT, 'a') as f:
            f.write(f"# DAVKA_START\n")
            f.write(f"DAVKA={cislo_davky}\n")
            f.write(f"START_X={x_start}\n")
            f.write(f"INCREMENT={inkrement}\n")
            f.write(f"CONSTANT={konstanta}\n")
            f.write(f"LINE_COUNT={pocet_radku}\n")
            f.write(f"# DAVKA_END\n")
        
        velikost_dat = os.stat(NAZEV_DAT)[6]
        print(f"  Dávka {cislo_davky} uložena do {NAZEV_DAT} (celková velikost: {velikost_dat} bytů)")
        return True
    except Exception as e:
        print(f"  Chyba při ukládání dávky: {e}")
        return False

def smaz_txt():
    """Smaže dočasný .txt soubor"""
    try:
        os.remove(NAZEV_TXT)
        print(f"  Dočasný soubor {NAZEV_TXT} smazán.")
    except:
        pass  # Soubor možná neexistuje, nevadí

