print(f"Limit místa pro uložení dávky: {LIMIT_MISTA}%")
print("=" * 50)

cislo_davky = 1

try:
    while cislo_davky <= POCET_DAVEK:
        print(f"\n>>> DÁVKA {cislo_davky}/{POCET_DAVEK} <<<")
        
        # Uložíme start X pro tuto dávku
        x_start_davky = x
        pocet_radku_davky = 0
        
        smaz_txt()  # Ujistíme se, že začínáme čistě
        
        # Generování dokud nedojde místo
        while True:
            volne_procent = kontrola_volneho_mista()
            
            if volne_procent < (100 - LIMIT_MISTA):
                print(f"  Disk zaplněn na {100 - volne_procent:.1f}%, ukládám dávku {cislo_davky}...")
                break
            
            # Výpočet a zápis řádku
            vysledek = konstanta * x
            radek = f"Číslo krát {x} = {vysledek}\n"
            
            with open(NAZEV_TXT, "a") as soubor:
                soubor.write(radek)
            
            x += inkrement
            pocet_radku_davky += 1
            
            if pocet_radku_davky % 500 == 0:
                print(f"  Řádků v dávce: {pocet_radku_davky}, volné místo: {volne_procent:.1f}%")
        
        # Uložit tuto dávku do společného .dat souboru
        pridej_davku_do_souboru(cislo_davky, x_start_davky, inkrement, konstanta, pocet_radku_davky)
        
        # Smazat dočasný .txt
        smaz_txt()
        
        print(f"  Dávka {cislo_davky} hotova! ({pocet_radku_davky} řádků)")
        cislo_davky += 1

    print("\n" + "=" * 50)
    print(f"HOTOVO! Všechny {POCET_DAVEK} dávky dokončeny!")
    velikost_dat = os.stat(NAZEV_DAT)[6]
    print(f"Výsledný soubor: {NAZEV_DAT} ({velikost_dat} bytů)")
    print("Přenes soubor na PC a dekomprimuj pomocí decompress_pc.py")

except KeyboardInterrupt:
    print(f"\nProgram přerušen uživatelem po {cislo_davky - 1} dávkách.")
